local ChocolateConfectioner = {}
local PRODUCTS = {
    plain_chocolate_bar = { name = "Navadna čokoladna tablica", woodCost = 1, sugarCost = 1, time = 4, cost = 50, happiness = 3, food = 12, description = "Navadna čokoladna tablica za trgovce." },
    spiced_chocolate_disc = { name = "Začinjen čokoladni disk", woodCost = 1, sugarCost = 1, spiceCost = 1, time = 6, cost = 130, happiness = 4, food = 18, prestige = 2, description = "Začinjen čokoladni disk za trgovce." },
    silver_wrapped_chocolate = { name = "Srebrnoolubljeni čokolada", woodCost = 1, sugarCost = 1, silverCost = 1, spiceCost = 1, time = 9, cost = 320, happiness = 5, food = 26, prestige = 6, description = "Srebrnoolubljeni čokolada za plemiče." },
    gold_foil_chocolate = { name = "Zlatofolijna čokolada", woodCost = 1, sugarCost = 2, goldCost = 1, silverCost = 1, spiceCost = 1, time = 13, cost = 760, happiness = 6, food = 36, prestige = 14, description = "Zlatofolijna čokolada za visoke plemiče." },
    jewel_topped_praline = { name = "Draguljasta pralina", woodCost = 1, sugarCost = 2, goldCost = 1, silverCost = 1, jewelCost = 1, spiceCost = 1, time = 17, cost = 1700, happiness = 8, food = 50, prestige = 27, description = "Pralina z draguljem za visoko plemstvo." },
    royal_grand_chocolate_box = { name = "Kraljevski veliki čokoladni zaboj", woodCost = 2, sugarCost = 3, goldCost = 2, silverCost = 2, jewelCost = 2, pearlCost = 2, spiceCost = 2, time = 24, cost = 3900, happiness = 13, food = 80, prestige = 58, description = "Veliki kraljevski čokoladni zaboj z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    confection_cottage = { name = "Konditorska koča", cost = { gold = 240, wood = 120, stone = 100, sugar = 6 }, upkeep = 5, qualityBonus = 5 },
    chocolate_loft = { name = "Čokoladna podstrešje", cost = { gold = 880, wood = 240, stone = 240, silver = 6, sugar = 8 }, upkeep = 20, qualityBonus = 18 },
    master_chocolatier_atelier = { name = "Mojstrski čokoladni atelje", cost = { gold = 2400, wood = 360, stone = 480, silver = 30, gold = 6 }, upkeep = 55, qualityBonus = 30 },
    royal_chocolate_palace = { name = "Kraljevska čokoladna palača", cost = { gold = 9800, wood = 580, stone = 740, gold = 60, jewel = 16 }, upkeep = 195, qualityBonus = 55, prestigeBonus = 50 },
}
ChocolateConfectioner.woodStock = 14; ChocolateConfectioner.sugarStock = 14; ChocolateConfectioner.spiceStock = 8; ChocolateConfectioner.silverStock = 6; ChocolateConfectioner.goldStock = 6; ChocolateConfectioner.jewelStock = 4; ChocolateConfectioner.pearlStock = 4
ChocolateConfectioner.productStock = {}; ChocolateConfectioner.buildings = {}; ChocolateConfectioner.maker = nil; ChocolateConfectioner.activeMaking = {}; ChocolateConfectioner.totalProducts = 0; ChocolateConfectioner.dayTimer = 0
function ChocolateConfectioner.init() ChocolateConfectioner.woodStock=14; ChocolateConfectioner.sugarStock=14; ChocolateConfectioner.spiceStock=8; ChocolateConfectioner.silverStock=6; ChocolateConfectioner.goldStock=6; ChocolateConfectioner.jewelStock=4; ChocolateConfectioner.pearlStock=4; ChocolateConfectioner.productStock={}; ChocolateConfectioner.buildings={}; ChocolateConfectioner.maker=nil; ChocolateConfectioner.activeMaking={}; ChocolateConfectioner.totalProducts=0; ChocolateConfectioner.dayTimer=0; print("[ChocolateConfectioner] Royal Chocolate Confectioner System initialized (6 products, 4 buildings)") end
function ChocolateConfectioner.hireMaker(n,s) s=s or math.random(55,90); local c=500+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ChocolateConfectioner.maker={name=n or ("Čokoladar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Čokoladar najet: %s (spretnost: %d)",ChocolateConfectioner.maker.name,s),"success") end; return true end
function ChocolateConfectioner.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ChocolateConfectioner.build(id) local ok,e=ChocolateConfectioner.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ChocolateConfectioner.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ChocolateConfectioner.getQualityBonus() local b=0; for _,bd in ipairs(ChocolateConfectioner.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ChocolateConfectioner.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and ChocolateConfectioner.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.sugarCost and ChocolateConfectioner.sugarStock<(d.sugarCost or 0) then return false,"Premalo sladkorja" end; if d.spiceCost and ChocolateConfectioner.spiceStock<(d.spiceCost or 0) then return false,"Premalo začimb" end; if d.silverCost and ChocolateConfectioner.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ChocolateConfectioner.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ChocolateConfectioner.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ChocolateConfectioner.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ChocolateConfectioner.buildings==0 then return false,"Potrebna konditorska koča" end; if not ChocolateConfectioner.maker then return false,"Potreben čokoladar" end; return true end
function ChocolateConfectioner.make(pt,qty) qty=qty or 1; local ok,e=ChocolateConfectioner.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then ChocolateConfectioner.woodStock=ChocolateConfectioner.woodStock-d.woodCost*qty end; if d.sugarCost then ChocolateConfectioner.sugarStock=ChocolateConfectioner.sugarStock-d.sugarCost*qty end; if d.spiceCost then ChocolateConfectioner.spiceStock=ChocolateConfectioner.spiceStock-d.spiceCost*qty end; if d.silverCost then ChocolateConfectioner.silverStock=ChocolateConfectioner.silverStock-d.silverCost*qty end; if d.goldCost then ChocolateConfectioner.goldStock=ChocolateConfectioner.goldStock-d.goldCost*qty end; if d.jewelCost then ChocolateConfectioner.jewelStock=ChocolateConfectioner.jewelStock-d.jewelCost*qty end; if d.pearlCost then ChocolateConfectioner.pearlStock=ChocolateConfectioner.pearlStock-d.pearlCost*qty end; local t=d.time; if ChocolateConfectioner.maker then t=math.max(1,t-math.floor(ChocolateConfectioner.maker.skill/13)) end; table.insert(ChocolateConfectioner.activeMaking,{id="chocolate_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=d.food or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Priprava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ChocolateConfectioner.completeMaking(m) local q=1.0+(ChocolateConfectioner.getQualityBonus()/100); if ChocolateConfectioner.maker then q=q+(ChocolateConfectioner.maker.skill/150) end; q=math.min(2.4,q); ChocolateConfectioner.productStock[m.productType]=(ChocolateConfectioner.productStock[m.productType] or 0)+m.quantity; ChocolateConfectioner.totalProducts=ChocolateConfectioner.totalProducts+m.quantity; if m.food>0 and _G.state then _G.state.food=(_G.state.food or 0)+m.food end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ChocolateConfectioner.maker then ChocolateConfectioner.maker.itemsMade=ChocolateConfectioner.maker.itemsMade+m.quantity; if math.random()<0.25 then ChocolateConfectioner.maker.skill=math.min(100,ChocolateConfectioner.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Čokolada pripravljena: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"chocolate.completed",{productName=m.productName,food=m.food,prestige=m.prestige,happiness=m.happiness}) end end
function ChocolateConfectioner.update(dt) if not _G.state then return end; ChocolateConfectioner.dayTimer=ChocolateConfectioner.dayTimer+dt; if ChocolateConfectioner.dayTimer>=30 then ChocolateConfectioner.dayTimer=0; for i=#ChocolateConfectioner.activeMaking,1,-1 do local m=ChocolateConfectioner.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ChocolateConfectioner.completeMaking(m); table.remove(ChocolateConfectioner.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ChocolateConfectioner.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ChocolateConfectioner.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ChocolateConfectioner.getStats() return {woodStock=ChocolateConfectioner.woodStock,sugarStock=ChocolateConfectioner.sugarStock,spiceStock=ChocolateConfectioner.spiceStock,silverStock=ChocolateConfectioner.silverStock,goldStock=ChocolateConfectioner.goldStock,jewelStock=ChocolateConfectioner.jewelStock,pearlStock=ChocolateConfectioner.pearlStock,productStock=ChocolateConfectioner.productStock,numBuildings=#ChocolateConfectioner.buildings,hasMaker=ChocolateConfectioner.maker~=nil,makerName=ChocolateConfectioner.maker and ChocolateConfectioner.maker.name or "—",makerSkill=ChocolateConfectioner.maker and ChocolateConfectioner.maker.skill or 0,activeMaking=#ChocolateConfectioner.activeMaking,totalProducts=ChocolateConfectioner.totalProducts} end
return ChocolateConfectioner
